    wo_state.mode = WO_NORMAL;
    wo_state.clean = 0U;
    wo_state.elapsed = 0U;
    wo_state.dissipated_energy_j = 0.0;
    for (i = 0; i < 4; i++)
        wo_state.previous_wheel_torque_nm[i] = 0.0;
    wo_output.mode = WO_NORMAL;
    wo_output.clean = 0U;
    wo_output.elapsed = 0U;
    return;
}

for (i = 0; i < 4; i++) {
    double a = fabs(wo_input.wheels[i].speed_rad_s);
    if (a > max_abs)
        max_abs = a;
}
wo_output.maximum_speed_rad_s = max_abs;
wo_output.momentum_nms = h;
wo_output.momentum_norm_nms = adcs_vec3_norm(&h);

switch (wo_state.mode) {
case WO_NORMAL:
    wo_state.clean = 0U;
    if (max_abs >= wo_config.trip_rad_s) {
        wo_state.mode = WO_BRAKE;
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
    } else if (max_abs >= wo_config.warn_rad_s) {
        wo_state.mode = WO_DERATE;
        wo_state.clean = 0U;
    } else {
        wo_state.clean = 0U;
    }
    break;
case WO_DERATE:
    if (max_abs >= wo_config.trip_rad_s) {
        wo_state.mode = WO_BRAKE;
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
    } else if (max_abs <= wo_config.release_rad_s) {
        wo_state.clean++;
        if (wo_state.clean >= wo_config.release_cycles) {
            wo_state.mode = WO_NORMAL;
            wo_state.clean = 0U;
        }
    } else {
        wo_state.clean = 0U;
    }
    break;
case WO_BRAKE:
    if (max_abs <= wo_config.release_rad_s) {
        if (wo_state.elapsed >= wo_config.minimum_brake_cycles)
            wo_state.clean++;
        else
            wo_state.clean = 0U;
        if (wo_state.clean >= wo_config.release_cycles) {
            wo_state.mode = WO_COOLDOWN;
            wo_state.clean = 0U;
            wo_state.elapsed = 0U;
        }
    } else {
        wo_state.clean = 0U;
    }
    break;
case WO_COOLDOWN:
    if (max_abs >= wo_config.trip_rad_s) {
        wo_state.mode = WO_BRAKE;
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
    } else {
        wo_state.elapsed++;
        if (wo_state.elapsed >= wo_config.cooldown_cycles) {
            wo_state.mode = WO_NORMAL;
            wo_state.clean = 0U;
            wo_state.elapsed = 0U;
        }
    }
    break;
case WO_FAULT:
default:
    break;
}

if (wo_state.mode == WO_DERATE) {
    double span = wo_config.trip_rad_s - wo_config.release_rad_s;
    for (i = 0; i < 4; i++) {
        double s = wo_input.wheels[i].speed_rad_s;
        double a = fabs(s);
        if (a > wo_config.release_rad_s && span > 0.0) {
            double mag = wo_config.derate_torque_nm * (a - wo_config.release_rad_s) / span;
            if (mag > wo_config.derate_torque_nm)
                mag = wo_config.derate_torque_nm;
            target[i] = (s > 0.0) ? -mag : ((s < 0.0) ? mag : 0.0);
        } else {
            target[i] = 0.0;
        }
    }
} else if (wo_state.mode == WO_BRAKE) {
    for (i = 0; i < 4; i++) {
        double s = wo_input.wheels[i].speed_rad_s;
        if (s > 0.0)
            target[i] = -wo_config.brake_torque_nm;
        else if (s < 0.0)
            target[i] = wo_config.brake_torque_nm;
        else
            target[i] = 0.0;
    }
} else {
    for (i = 0; i < 4; i++)
        target[i] = 0.0;
}

for (i = 0; i < 4; i++) {
    double prev = wo_state.previous_wheel_torque_nm[i];
    double d = target[i] - prev;
    double slew = wo_config.torque_slew_nm_per_cycle;
    if (d > slew)
        d = slew;
    else if (d < -slew)
        d = -slew;
    else
        d = d;
    limited[i] = prev + d;
    wo_state.previous_wheel_torque_nm[i] = limited[i];
    wo_output.wheel_torque_nm[i] = limited[i];
}

for (i = 0; i < 4; i++) {
    double s = wo_input.wheels[i].speed_rad_s;
    double t = limited[i];
    power += -t * s;
    if (fabs(t) > 0.0)
        mask |= (uint32_t)(1U << i);
}
wo_output.limited_mask = mask;
wo_output.brake_power_w = power;
wo_state.dissipated_energy_j += -power * wo_config.dt_s;
wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;
wo_output.mode = wo_state.mode;
wo_output.clean = wo_state.clean;
wo_output.elapsed = wo_state.elapsed;
